1	package edgefleet
2	
3	import (
4		"bufio"
5		"bytes"
6		"encoding/json"
7		"fmt"
8		"io"
9		"math"
10		"sort"
11		"strconv"
12		"strings"
13	)
14	
15	// AggregateResult is one closed window output line.
16	type AggregateResult struct {
17		Key   string `json:"key"`
18		Start int64  `json:"start"`
19		End   int64  `json:"end"`
20		Count int64  `json:"count"`
21		Sum   int64  `json:"sum"`
22	}
23	
24	// InputError reports a fatal problem with one physical input line.
25	type InputError struct {
26		Line   int
27		Reason string
28	}
29	
30	func (e *InputError) Error() string {
31		return fmt.Sprintf("line %d: %s", e.Line, e.Reason)
32	}
33	
34	type windowID struct {
35		start int64 // inclusive window start in milliseconds since time zero
36		key   string
37	}
38	
39	type windowState struct {
40		end   int64 // exclusive window end in milliseconds
41		count int64
42		sum   int64
43	}
44	
45	// RunAggregate reads line-delimited JSON records from r and writes closed
46	// fixed window results, one JSON object per line, to out. windowMillis must
47	// be a positive signed 64-bit integer. Windows are fixed-length, start at
48	// time zero and use a left-closed right-open interval. Closure is driven
49	// solely by input watermarks: a window whose end is less than or equal to the
50	// current watermark is emitted once, ordered by end ascending and then by key
51	// in UTF-8 byte order. Late events (event time below the current watermark)
52	// are reported on lateLog with their physical line number and skipped. Fatal
53	// record problems return *InputError; results already written to out stay
54	// written, and open windows are not flushed at end of input.
55	//
56	// This is the legacy single-watermark mode: records carry no partition field
57	// and any extra fields are ignored. Use RunAggregatePartitioned to merge
58	// several independent input sources of the same stream, or
59	// RunAggregateSliding to emit overlapping windows at a shorter interval.
60	func RunAggregate(r io.Reader, windowMillis int64, out io.Writer, lateLog io.Writer) error {
61		return RunAggregatePartitionedSliding(r, windowMillis, windowMillis, 0, out, lateLog)
62	}
63	
64	// RunAggregateSliding is RunAggregate with overlapping sliding windows. The
65	// window length is windowMillis and consecutive window starts are slideMillis
66	// apart, beginning at time zero: 0, slideMillis, 2*slideMillis, ... Each
67	// window is left-closed right-open and no window with a negative start is
68	// created. slideMillis must be a positive signed 64-bit integer no greater
69	// than windowMillis and does not have to divide it; slideMillis equal to
70	// windowMillis is exactly RunAggregate's fixed-window behavior. A valid event
71	// is counted once in every window that contains its event time, adding to
72	// that window's per-key count and the full value to its sum. Everything else
73	// (watermark-only closure, ordering, late reporting, overflow handling and
74	// end-of-input behavior) is identical to RunAggregate.
75	func RunAggregateSliding(r io.Reader, windowMillis, slideMillis int64, out io.Writer, lateLog io.Writer) error {
76		return RunAggregatePartitionedSliding(r, windowMillis, slideMillis, 0, out, lateLog)
77	}
78	
79	// RunAggregatePartitioned is RunAggregatePartitionedSliding with slideMillis
80	// equal to windowMillis (non-overlapping fixed windows).
81	func RunAggregatePartitioned(r io.Reader, windowMillis, partitions int64, out io.Writer, lateLog io.Writer) error {
82		return RunAggregatePartitionedSliding(r, windowMillis, windowMillis, partitions, out, lateLog)
83	}
84	
85	// RunAggregatePartitionedSliding combines sliding windows (see
86	// RunAggregateSliding) with partitioned inputs: events from different
87	// partitions merge into one count and sum per key and window, and both the
88	// late-event check and window closure use the effective (minimum) watermark.
89	// windowMillis and slideMillis are validated exactly as in
90	// RunAggregateSliding. partitions selects the input mode:
91	//
92	//   - partitions == 0: legacy single-watermark mode. Records do not carry a
93	//     partition field; any extra fields are ignored.
94	//
95	//   - partitions > 0: partitioned mode, merging partitions independent input
96	//     sources of the same stream. Every event and watermark record must carry
97	//     an integer "partition" in [0,partitions). Each partition advances its
98	//     own watermark; no effective watermark exists until every partition has
99	//     reported at least once, afterwards the effective watermark is the
100	//     minimum of the per-partition values. Window closure and late-event
101	//     checks use this minimum, so one partition's larger watermark can never
102	//     close a window or drop an event ahead of the others. A partition
103	//     watermark may repeat or jump forward but never move backwards.
104	//
105	//     A partition may be declared idle with
106	//     {"type":"idle","partition":p}. An idle partition stops contributing to
107	//     the effective watermark: non-idle partitions that have not reported a
108	//     watermark yet still keep the effective watermark unknown, while a
109	//     partition that never reported may itself be declared idle. When every
110	//     remaining (non-idle) partition has reported, the effective watermark is
111	//     their minimum and the idle record itself can close windows. If all
112	//     partitions are idle, the last produced effective watermark is retained;
113	//     when none was ever produced it stays unknown. Idleness is declared by
114	//     the input only, never inferred from time; a repeated idle declaration
115	//     is a no-op. The next watermark record for that partition resumes it:
116	//     its time must be at least both the partition's previous watermark and
117	//     the current effective watermark. An event for an idle partition is
118	//     fatal; it never resumes implicitly.
119	//
120	// partitions < 0 is an error. Windows, ordering, late-event reporting,
121	// overflow checks and end-of-input behavior are otherwise identical to
122	// RunAggregateSliding.
123	func RunAggregatePartitionedSliding(r io.Reader, windowMillis, slideMillis, partitions int64, out io.Writer, lateLog io.Writer) error {
124		if windowMillis <= 0 {
125			return fmt.Errorf("window length must be a positive signed 64-bit integer, got %d", windowMillis)
126		}
127		if slideMillis <= 0 {
128			return fmt.Errorf("slide interval must be a positive signed 64-bit integer, got %d", slideMillis)
129		}
130		if slideMillis > windowMillis {
131			return fmt.Errorf("slide interval %d must not exceed window length %d", slideMillis, windowMillis)
132		}
133		if partitions < 0 {
134			return fmt.Errorf("partition count must be a positive signed 64-bit integer, got %d", partitions)
135		}
136		s := &aggregateState{
137			windowMillis:  windowMillis,
138			slideMillis:   slideMillis,
139			windows:       make(map[windowID]*windowState),
140			out:           out,
141			lateLog:       lateLog,
142			partitions:    partitions,
143			partWatermark: make(map[int64]*int64),
144			idle:          make(map[int64]bool),
145		}
146	
147		scanner := bufio.NewScanner(r)
148		scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024*1024)
149		lineNo := 0
150		for scanner.Scan() {
151			lineNo++
152			line := strings.TrimSuffix(scanner.Text(), "\r")
153			if strings.TrimSpace(line) == "" {
154				continue
155			}
156			if err := s.processLine(line, lineNo); err != nil {
157				return err
158			}
159		}
160		return scanner.Err()
161	}
162	
163	type aggregateState struct {
164		windowMillis int64
165		slideMillis  int64 // distance between consecutive window starts; equals windowMillis for fixed windows
166		windows      map[windowID]*windowState
167		out          io.Writer
168		lateLog      io.Writer
169	
170		partitions    int64 // 0 = legacy single-watermark mode
171		watermark     *int64
172		partWatermark map[int64]*int64 // partition -> last watermark; partitioned mode only
173		idle          map[int64]bool   // partitions declared idle in the input; partitioned mode only
174	}
175	
176	func (s *aggregateState) processLine(line string, lineNo int) error {
177		var obj map[string]json.RawMessage
178		if err := json.Unmarshal([]byte(line), &obj); err != nil {
179			return &InputError{Line: lineNo, Reason: "invalid JSON record: " + err.Error()}
180		}
181	
182		typeRaw, ok := obj["type"]
183		if !ok {
184			return &InputError{Line: lineNo, Reason: `missing required string field "type"`}
185		}
186		recordType, err := decodeString(typeRaw, "type")
187		if err != nil {
188			return &InputError{Line: lineNo, Reason: err.Error()}
189		}
190	
191		switch recordType {
192		case "event":
193			return s.processEvent(obj, lineNo)
194		case "watermark":
195			return s.processWatermark(obj, lineNo)
196		case "idle":
197			// Only partitioned mode knows idle declarations; legacy
198			// single-watermark mode treats it as any unknown record type.
199			if s.partitions == 0 {
200				return &InputError{Line: lineNo, Reason: fmt.Sprintf("unknown record type %q", recordType)}
201			}
202			return s.processIdle(obj, lineNo)
203		default:
204			return &InputError{Line: lineNo, Reason: fmt.Sprintf("unknown record type %q", recordType)}
205		}
206	}
207	
208	// floorDiv returns math.Floor(a/b) for b > 0; Go's / truncates toward zero,
209	// so negative numerators need explicit adjustment.
210	func floorDiv(a, b int64) int64 {
211		q := a / b
212		if a%b != 0 && a < 0 {
213			q--
214		}
215		return q
216	}
217	
218	// containingWindowBounds returns the first and last (inclusive) window index
219	// whose window [k*slideMillis, k*slideMillis+windowMillis) contains
220	// eventTime. Windows start at 0, slideMillis, 2*slideMillis, ... and none
221	// with a negative start is created, so the first index is clamped to zero.
222	// The last index is eventTime/slideMillis, so an event at a window end is
223	// outside that window.
224	func (s *aggregateState) containingWindowBounds(eventTime int64) (first, last int64) {
225		last = eventTime / s.slideMillis
226		first = floorDiv(eventTime-s.windowMillis, s.slideMillis) + 1
227		if first < 0 {
228			first = 0
229		}
230		return first, last
231	}
232	
233	// containingWindowCount returns how many windows contain eventTime.
234	func (s *aggregateState) containingWindowCount(eventTime int64) int64 {
235		first, last := s.containingWindowBounds(eventTime)
236		return last - first + 1
237	}
238	
239	// containingStart returns the start of the containing window reached back by
240	// offset indices from the last one (offset 0 = last window).
241	func (s *aggregateState) containingStart(eventTime, offset int64) int64 {
242		last := eventTime - eventTime%s.slideMillis
243		return last - offset*s.slideMillis
244	}
245	
246	// firstOverflowingStart reports the start of the earliest containing window
247	// whose end (start + windowMillis) leaves the signed 64-bit range, or -1 when
248	// every containing window fits. Containing starts are an ascending arithmetic
249	// sequence with step slideMillis, so overflow (if any) is a suffix; this
250	// computes its first member directly instead of walking the sequence.
251	func (s *aggregateState) firstOverflowingStart(eventTime int64) int64 {
252		n := s.containingWindowCount(eventTime)
253		lowest := s.containingStart(eventTime, n-1) // earliest containing start; never negative
254		maxSafeStart := int64(math.MaxInt64 - s.windowMillis)
255		if lowest > maxSafeStart {
256			return lowest
257		}
258		safe := (maxSafeStart-lowest)/s.slideMillis + 1 // number of containing starts that fit
259		if safe < n {
260			// Reach back from last, which is at most eventTime, so the
261			// subtraction cannot leave the signed 64-bit range.
262			return s.containingStart(eventTime, n-1-safe)
263		}
264		return -1
265	}
266	
267	func (s *aggregateState) processEvent(obj map[string]json.RawMessage, lineNo int) error {
268		key, err := requiredString(obj, "key", lineNo)
269		if err != nil {
270			return err
271		}
272		if key == "" {
273			return &InputError{Line: lineNo, Reason: `field "key" must be a non-empty string`}
274		}
275		eventTime, err := requiredNonNegInt64(obj, "time", lineNo)
276		if err != nil {
277			return err
278		}
279		value, err := requiredInt64(obj, "value", lineNo)
280		if err != nil {
281			return err
282		}
283		p, err := s.requiredPartition(obj, lineNo)
284		if err != nil {
285			return err
286		}
287		if s.partitions > 0 && s.idle[p] {
288			return &InputError{Line: lineNo, Reason: fmt.Sprintf("event for idle partition %d is not allowed; send a watermark to resume it first", p)}
289		}
290	
291		if s.watermark != nil && eventTime < *s.watermark {
292			fmt.Fprintf(s.lateLog, "line %d: late event time=%d below current watermark %d, skipped\n", lineNo, eventTime, *s.watermark)
293			return nil
294		}
295	
296		n := s.containingWindowCount(eventTime)
297	
298		// A window whose end leaves the signed 64-bit range is fatal for the
299		// whole input line; check before updating any window state.
300		if badStart := s.firstOverflowingStart(eventTime); badStart >= 0 {
301			return &InputError{Line: lineNo, Reason: fmt.Sprintf("window end overflow for key %q window starting at %d with length %d", key, badStart, s.windowMillis)}
302		}
303	
304		// Add the event once to each containing window, in ascending start
305		// order. An overflow here stops processing immediately; already closed
306		// (and thus already written) windows are unaffected.
307		for i := n - 1; i >= 0; i-- {
308			start := s.containingStart(eventTime, i)
309			end := start + s.windowMillis
310			id := windowID{start: start, key: key}
311			st := s.windows[id]
312			if st == nil {
313				st = &windowState{end: end}
314				s.windows[id] = st
315			}
316			if st.count == math.MaxInt64 {
317				return &InputError{Line: lineNo, Reason: fmt.Sprintf("event count overflow for key %q window [%d,%d)", key, start, end)}
318			}
319			if value > 0 && st.sum > math.MaxInt64-value {
320				return &InputError{Line: lineNo, Reason: fmt.Sprintf("cumulative sum overflow for key %q window [%d,%d): %d + %d", key, start, end, st.sum, value)}
321			}
322			if value < 0 && st.sum < math.MinInt64-value {
323				return &InputError{Line: lineNo, Reason: fmt.Sprintf("cumulative sum overflow for key %q window [%d,%d): %d + %d", key, start, end, st.sum, value)}
324			}
325			st.count++
326			st.sum += value
327		}
328		return nil
329	}
330	
331	func (s *aggregateState) processWatermark(obj map[string]json.RawMessage, lineNo int) error {
332		next, err := requiredNonNegInt64(obj, "time", lineNo)
333		if err != nil {
334			return err
335		}
336		p, err := s.requiredPartition(obj, lineNo)
337		if err != nil {
338			return err
339		}
340	
341		if s.partitions == 0 {
342			if s.watermark != nil && next < *s.watermark {
343				return &InputError{Line: lineNo, Reason: fmt.Sprintf("watermark moved backwards from %d to %d", *s.watermark, next)}
344			}
345			s.watermark = &next
346		} else {
347			resuming := s.idle[p]
348			if resuming {
349				// A resume watermark must be at least the partition's previous
350				// watermark and the effective watermark produced while it was
351				// idle; equality on either boundary resumes.
352				if prev, ok := s.partWatermark[p]; ok && next < *prev {
353					return &InputError{Line: lineNo, Reason: fmt.Sprintf("resume watermark %d for partition %d is below its previous watermark %d", next, p, *prev)}
354				}
355				if s.watermark != nil && next < *s.watermark {
356					return &InputError{Line: lineNo, Reason: fmt.Sprintf("resume watermark %d for partition %d is below the current effective watermark %d", next, p, *s.watermark)}
357				}
358				delete(s.idle, p)
359			} else if prev, ok := s.partWatermark[p]; ok && next < *prev {
360				return &InputError{Line: lineNo, Reason: fmt.Sprintf("watermark for partition %d moved backwards from %d to %d", p, *prev, next)}
361			}
362			s.partWatermark[p] = &next
363			if effective := s.effectiveWatermark(); effective != nil {
364				s.watermark = effective
365			}
366		}
367	
368		if s.watermark == nil {
369			return nil
370		}
371		return s.closeWindows(*s.watermark)
372	}
373	
374	// processIdle declares a partition idle: it stops contributing to the
375	// effective watermark until its next watermark record. The declaration
376	// itself may advance the effective watermark and close windows.
377	func (s *aggregateState) processIdle(obj map[string]json.RawMessage, lineNo int) error {
378		p, err := s.requiredPartition(obj, lineNo)
379		if err != nil {
380			return err
381		}
382		wasIdle := s.idle[p]
383		s.idle[p] = true
384	
385		// Recompute the effective watermark. With the partition excluded, the
386		// remaining non-idle partitions determine it; if every partition is idle
387		// the last produced effective watermark is retained instead of clearing.
388		// Repeated idle declarations do not change the state of the windows.
389		if !wasIdle {
390			if next := s.effectiveWatermark(); next != nil {
391				s.watermark = next
392			}
393		}
394		if s.watermark == nil {
395			return nil
396		}
397		return s.closeWindows(*s.watermark)
398	}
399	
400	// effectiveWatermark returns the minimum watermark over the non-idle
401	// partitions once each of them has reported at least once, or nil
402	// otherwise. When every partition is idle, nil is returned so the caller
403	// keeps the last produced effective watermark.
404	func (s *aggregateState) effectiveWatermark() *int64 {
405		active := s.partitions - int64(len(s.idle))
406		if active <= 0 {
407			return nil
408		}
409		var min int64
410		first := true
411		for p := int64(0); p < s.partitions; p++ {
412			if s.idle[p] {
413				continue
414			}
415			w, ok := s.partWatermark[p]
416			if !ok {
417				return nil
418			}
419			if first || *w < min {
420				min = *w
421				first = false
422			}
423		}
424		return &min
425	}
426	
427	// requiredPartition returns the record's partition index. In legacy mode it
428	// returns 0 without inspecting the record, so extra fields stay ignored.
429	func (s *aggregateState) requiredPartition(obj map[string]json.RawMessage, lineNo int) (int64, error) {
430		if s.partitions == 0 {
431			return 0, nil
432		}
433		p, err := requiredInt64(obj, "partition", lineNo)
434		if err != nil {
435			return 0, err
436		}
437		if p < 0 || p >= s.partitions {
438			return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("field %q must be an integer in range [0,%d), got %d", "partition", s.partitions, p)}
439		}
440		return p, nil
441	}
442	
443	func (s *aggregateState) closeWindows(watermark int64) error {
444		type pending struct {
445			id windowID
446			st *windowState
447		}
448		var ready []pending
449		for id, st := range s.windows {
450			if st.end <= watermark {
451				ready = append(ready, pending{id: id, st: st})
452			}
453		}
454		sort.Slice(ready, func(i, j int) bool {
455			if ready[i].st.end != ready[j].st.end {
456				return ready[i].st.end < ready[j].st.end
457			}
458			return ready[i].id.key < ready[j].id.key
459		})
460		for _, p := range ready {
461			encoded, err := json.Marshal(AggregateResult{
462				Key:   p.id.key,
463				Start: p.id.start,
464				End:   p.st.end,
465				Count: p.st.count,
466				Sum:   p.st.sum,
467			})
468			if err != nil {
469				return err
470			}
471			if _, err := s.out.Write(append(encoded, '\n')); err != nil {
472				return err
473			}
474			delete(s.windows, p.id)
475		}
476		return nil
477	}
478	
479	func requiredString(obj map[string]json.RawMessage, field string, lineNo int) (string, error) {
480		raw, ok := obj[field]
481		if !ok {
482			return "", &InputError{Line: lineNo, Reason: fmt.Sprintf("missing required string field %q", field)}
483		}
484		value, err := decodeString(raw, field)
485		if err != nil {
486			return "", &InputError{Line: lineNo, Reason: err.Error()}
487		}
488		return value, nil
489	}
490	
491	func requiredInt64(obj map[string]json.RawMessage, field string, lineNo int) (int64, error) {
492		raw, ok := obj[field]
493		if !ok {
494			return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("missing required integer field %q", field)}
495		}
496		value, err := decodeInt64(raw, field)
497		if err != nil {
498			return 0, &InputError{Line: lineNo, Reason: err.Error()}
499		}
500		return value, nil
501	}
502	
503	func requiredNonNegInt64(obj map[string]json.RawMessage, field string, lineNo int) (int64, error) {
504		value, err := requiredInt64(obj, field, lineNo)
505		if err != nil {
506			return 0, err
507		}
508		if value < 0 {
509			return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("field %q must be a non-negative integer, got %d", field, value)}
510		}
511		return value, nil
512	}
513	
514	func decodeString(raw json.RawMessage, field string) (string, error) {
515		trimmed := bytes.TrimSpace(raw)
516		if len(trimmed) == 0 || trimmed[0] != '"' {
517			return "", fmt.Errorf("field %q must be a JSON string, got %s", field, string(trimmed))
518		}
519		var value string
520		if err := json.Unmarshal(trimmed, &value); err != nil {
521			return "", fmt.Errorf("field %q must be a JSON string: %v", field, err)
522		}
523		return value, nil
524	}
525	
526	func decodeInt64(raw json.RawMessage, field string) (int64, error) {
527		trimmed := bytes.TrimSpace(raw)
528		if len(trimmed) == 0 {
529			return 0, fmt.Errorf("field %q must be a signed 64-bit integer", field)
530		}
531		switch trimmed[0] {
532		case '"', '{', '[', 't', 'f', 'n':
533			return 0, fmt.Errorf("field %q must be a signed 64-bit integer, got %s", field, string(trimmed))
534		}
535		value, err := strconv.ParseInt(string(trimmed), 10, 64)
536		if err != nil {
537			if numErr, ok := err.(*strconv.NumError); ok && numErr.Err == strconv.ErrRange {
538				return 0, fmt.Errorf("field %q integer out of signed 64-bit range: %s", field, string(trimmed))
539			}
540			return 0, fmt.Errorf("field %q must be a signed 64-bit integer, got %s", field, string(trimmed))
541		}
542		return value, nil
543	}
